import heapq

from graph import dependents


class CycleError(ValueError):
    pass


class UnknownTaskError(ValueError):
    pass


def schedule(tasks: dict[str, list[str]]) -> list[str]:
    for name, deps in tasks.items():
        for dep in deps:
            if dep not in tasks:
                raise UnknownTaskError(f"{name} depends on unknown task {dep}")
    remaining = {name: len(deps) for name, deps in tasks.items()}
    ready = [name for name, count in remaining.items() if count == 0]
    heapq.heapify(ready)
    children = dependents(tasks)
    order = []
    while ready:
        name = heapq.heappop(ready)
        order.append(name)
        for child in children[name]:
            remaining[child] -= 1
            if remaining[child] == 0:
                heapq.heappush(ready, child)
    if len(order) != len(tasks):
        stuck = sorted(name for name, count in remaining.items() if count > 0)
        raise CycleError(f"could not schedule: {', '.join(stuck)}")
    return order
